def rope_theta(i: int, head_dim: int, base: int = 10000) -> float:
    """Fixed rotation frequency for dimension pair i, out of head_dim/2 pairs."""
    return round(base ** (-(2 * i) / head_dim), 6)

print(rope_theta(32, 128))

def rope_theta(i: int, head_dim: int, base: int = 10000) -> float:
    return round(base ** (-(2 * i) / head_dim), 6)

def rope_angle(pos: int, i: int, head_dim: int, base: int = 10000) -> float:
    """Angle dimension pair i has rotated by, by the time it reaches position pos."""
    theta = rope_theta(i, head_dim, base)
    return round(pos * theta, 4)

print(rope_angle(5, 32, 128))
